cat >> tests/tasks.test.ts <<'EOF'

describe("SL-008 list open tasks newest first, with an empty state", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  it("AC-3: an empty list answers 200 with no tasks", async () => {
    assert.deepEqual(await listTasks(server), []);
  });

  it("AC-3: the page has an empty-state element that is hidden by default and toggled by the script", async () => {
    const html = await (await fetch(`${server.baseUrl}/`)).text();
    const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    assert.match(html, /<[a-z]+(?=[^>]*id=["']empty-state["'])(?=[^>]*\bhidden\b)[^>]*>/);
    assert.match(script, /empty-state/);
    assert.match(script, /\.hidden\s*=\s*tasks\.length\s*>\s*0/);
  });

  it("AC-1: tasks added as A, B, C are listed C, B, A", async () => {
    for (const title of ["A", "B", "C"]) {
      assert.equal((await createTask(server, title)).status, 201);
      await new Promise((resolve) => setTimeout(resolve, 5));
    }
    const titles = (await listTasks(server)).map((t) => t.title);
    assert.deepEqual(titles, ["C", "B", "A"]);
  });

  it("AC-2: tasks created at the same instant are listed last-saved first, every time", async () => {
    const other = await startServer();
    try {
      const realNow = Date.now;
      void realNow;
      // Same-instant creation is forced by posting concurrently-fast; ties are checked by created_at equality.
      const titles = Array.from({ length: 30 }, (_, i) => `T${i}`);
      const ids: number[] = [];
      for (const title of titles) {
        const { task } = (await (await createTask(other, title)).json()) as { task: Task };
        ids.push(task.id);
      }
      const listed = await listTasks(other);
      const expected = [...listed].sort(
        (a, b) => b.created_at.localeCompare(a.created_at) || b.id - a.id,
      );
      assert.deepEqual(listed, expected);
      for (let run = 0; run < 3; run++) assert.deepEqual(await listTasks(other), listed);
      assert.ok(
        new Set(listed.map((t) => t.created_at)).size < listed.length,
        "expected some tasks to share a created_at so the tie-break is exercised",
      );
    } finally {
      await other.stop();
    }
  });

  it("AC-4: about 1000 tasks list in under 100 ms (p95) and under 400000 bytes", async () => {
    const big = await startServer();
    try {
      for (let i = 0; i < 1000; i += 50) {
        await Promise.all(
          Array.from({ length: 50 }, (_, j) => createTask(big, `Task number ${i + j} to do`)),
        );
      }
      const times: number[] = [];
      let bytes = 0;
      for (let i = 0; i < 20; i++) {
        const start = performance.now();
        const response = await fetch(`${big.baseUrl}/api/tasks`);
        bytes = (await response.arrayBuffer()).byteLength;
        times.push(performance.now() - start);
      }
      times.sort((a, b) => a - b);
      assert.ok(times[18] < 100, `p95 was ${times[18]} ms`);
      assert.ok(bytes < 400000, `body was ${bytes} bytes`);
    } finally {
      await big.stop();
    }
  });
});
EOF
